SourceCode.Declaration:
/// <summary>
/// Data event handler on <c>CustTable</c> to detect customer creation and relevant updates
/// and enqueue eligible B2C customers into <c>UTCSFCustomerPushQueue</c>.
/// Uses <c>DataEventHandler</c> instead of CoC so it remains resilient to optional parameter
/// changes on <c>CustTable.insert()</c> and <c>CustTable.update()</c> across D365 F&amp;O versions.
/// </summary>
public static class UTCSFCustTable_Extension
{
}

Method.Source:
[DataEventHandler(tableStr(CustTable), DataEventType::Inserted)]
public static void CustTable_onInserted(Common _sender, DataEventArgs _e)
{
    CustTable custTable = _sender as CustTable;

    if (custTable)
    {
        UTCSFCustomerChangeHandler::tryEnqueueCustTable(custTable, false);
    }
}

[DataEventHandler(tableStr(CustTable), DataEventType::Updated)]
public static void CustTable_onUpdated(Common _sender, DataEventArgs _e)
{
    CustTable custTable = _sender as CustTable;

    if (!custTable)
    {
        return;
    }

    CustTable origCustTable = custTable.orig();

    boolean hasGroupChange = (custTable.CustGroup != origCustTable.CustGroup);

    boolean hasRelevantChange = (hasGroupChange
                              || custTable.Blocked    != origCustTable.Blocked
                              || custTable.Party      != origCustTable.Party
                              || custTable.AccountNum != origCustTable.AccountNum);

    if (!hasRelevantChange)
    {
        return;
    }

    // Salesforce v1.6: if a customer moves from an in-scope group (e.g. Retail) to an
    // out-of-scope group (e.g. Coops), D365 must still push the update so Salesforce
    // excludes the customer from marketing audiences.
    boolean wasInScopeBeforeUpdate = false;
    if (hasGroupChange && origCustTable.CustGroup != '')
    {
        UTCSFCustomerPushService pushService = UTCSFCustomerPushService::construct();
        wasInScopeBeforeUpdate = pushService.isInScopeCustomerGroup(origCustTable.CustGroup);
    }

    UTCSFCustomerChangeHandler::tryEnqueueCustTable(custTable, wasInScopeBeforeUpdate);
}
